package com.tailstter.bluesky;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import org.json.*;import java.io.*;import java.net.*;import java.util.*;

public class MainActivity extends Activity {
  static final String PREF="bluesky"; LinearLayout root,feed; EditText handle,password,server,compose; String token; String base;
  int blue=Color.rgb(32,139,254);
  public void onCreate(Bundle b){super.onCreate(b); base=getPreferences(0).getString("server","http://tails1154.com:6483"); token=getPreferences(0).getString("token",null); if(token==null) login(); else home();}
  TextView tv(String s,int sp){TextView v=new TextView(this);v.setText(s);v.setTextSize(sp);v.setTextColor(Color.DKGRAY);v.setPadding(16,12,16,12);return v;}
  Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(14);b.setBackgroundColor(blue);return b;}
  void shell(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(245,248,250));setContentView(root); LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setBackgroundColor(Color.rgb(25,35,48));TextView title=tv("  BlueSky",20);title.setTextColor(Color.WHITE);bar.addView(title,new LinearLayout.LayoutParams(0,58,1));Button settings=btn("Server");settings.setOnClickListener(new View.OnClickListener(){public void onClick(View v){serverDialog();}});bar.addView(settings,new LinearLayout.LayoutParams(90,58));root.addView(bar);}
  void login(){shell(); LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(22,30,22,10);TextView h=tv("Sign in to BlueSky",24);h.setTextColor(blue);box.addView(h);handle=new EditText(this);handle.setHint("handle (for example, user.bsky.social)");box.addView(handle);password=new EditText(this);password.setHint("app password");password.setInputType(0x81);box.addView(password);Button go=btn("Sign in");box.addView(go);go.setOnClickListener(new View.OnClickListener(){public void onClick(View v){loginRequest();}});TextView hint=tv("Use a Bluesky app password. Your password is sent only to the bridge and is never stored by this app.",13);box.addView(hint);root.addView(box);}
  void loginRequest(){final String u=handle.getText().toString().trim(),p=password.getText().toString(); if(u.length()==0||p.length()==0){toast("Enter your handle and app password");return;} toast("Signing in…"); new Thread(new Runnable(){public void run(){try{String body="x_auth_mode=client_auth&x_auth_username="+enc(u)+"&x_auth_password="+enc(p);String r=http("POST",base+"/oauth/access_token",body,null);final String t=param(r,"oauth_token");if(t==null)throw new Exception("Bridge did not return a token");getPreferences(0).edit().putString("token",t).putString("server",base).commit();token=t;runOnUiThread(new Runnable(){public void run(){home();}});}catch(final Exception e){runOnUiThread(new Runnable(){public void run(){toast("Sign in failed: "+e.getMessage());}});}}}).start();}
  void home(){shell();LinearLayout tabs=new LinearLayout(this);tabs.setBackgroundColor(Color.WHITE);Button feedTab=btn("Timeline");Button search=btn("Search");Button profile=btn("Profile");Button post=btn("Compose");tabs.addView(feedTab,new LinearLayout.LayoutParams(0,52,1));tabs.addView(search,new LinearLayout.LayoutParams(0,52,1));tabs.addView(profile,new LinearLayout.LayoutParams(0,52,1));tabs.addView(post,new LinearLayout.LayoutParams(0,52,1));root.addView(tabs);feed=new LinearLayout(this);feed.setOrientation(LinearLayout.VERTICAL);ScrollView sc=new ScrollView(this);sc.addView(feed);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));feedTab.setOnClickListener(new View.OnClickListener(){public void onClick(View v){loadTimeline();}});search.setOnClickListener(new View.OnClickListener(){public void onClick(View v){searchDialog();}});profile.setOnClickListener(new View.OnClickListener(){public void onClick(View v){loadProfile();}});post.setOnClickListener(new View.OnClickListener(){public void onClick(View v){composeDialog();}});loadTimeline();}
  void loadTimeline(){feed.removeAllViews();feed.addView(tv("Loading timeline…",16));new Thread(new Runnable(){public void run(){try{String r=http("GET",base+"/1/statuses/home_timeline.json?count=50",null,token);final JSONArray a=new JSONArray(r);runOnUiThread(new Runnable(){public void run(){showPosts(a);}});}catch(final Exception e){runOnUiThread(new Runnable(){public void run(){feed.removeAllViews();feed.addView(tv("Could not load timeline: "+e.getMessage(),16));}});}}}).start();}
  void showPosts(JSONArray a){feed.removeAllViews();if(a.length()==0){feed.addView(tv("No posts yet. Follow people on Bluesky or compose a post.",16));return;}for(int i=0;i<a.length();i++){try{JSONObject p=a.getJSONObject(i),u=p.optJSONObject("user");LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(8,8,8,8);TextView who=tv(u.optString("name",u.optString("screen_name"))+"  @"+u.optString("screen_name"),15);who.setTextColor(blue);row.addView(who);row.addView(tv(p.optString("text"),17));row.addView(tv(p.optString("created_at"),11));feed.addView(row);View line=new View(this);line.setBackgroundColor(Color.LTGRAY);feed.addView(line,new LinearLayout.LayoutParams(-1,1));}catch(Exception e){}}
  }
  void loadProfile(){feed.removeAllViews();feed.addView(tv("Loading profile…",16));new Thread(new Runnable(){public void run(){try{final JSONObject p=new JSONObject(http("GET",base+"/1/account/verify_credentials.json",null,token));runOnUiThread(new Runnable(){public void run(){feed.removeAllViews();feed.addView(tv(p.optString("name"),24));feed.addView(tv("@"+p.optString("screen_name"),16));feed.addView(tv(p.optString("description"),16));feed.addView(tv("Posts: "+p.optInt("statuses_count")+"   Followers: "+p.optInt("followers_count"),14));}});}catch(final Exception e){runOnUiThread(new Runnable(){public void run(){feed.removeAllViews();feed.addView(tv("Could not load profile: "+e.getMessage(),16));}});}}}).start();}
  void searchDialog(){final EditText e=new EditText(this);e.setHint("Search posts");new AlertDialog.Builder(this).setTitle("Search BlueSky").setView(e).setNegativeButton("Cancel",null).setPositiveButton("Search",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){loadSearch(e.getText().toString());}}).show();}
  void loadSearch(final String query){if(query.trim().length()==0)return;feed.removeAllViews();feed.addView(tv("Searching…",16));new Thread(new Runnable(){public void run(){try{String r=http("GET",base+"/1/search/tweets.json?q="+enc(query)+"&count=50",null,token);final JSONObject o=new JSONObject(r);final JSONArray a=o.optJSONArray("statuses")==null?new JSONArray():o.optJSONArray("statuses");runOnUiThread(new Runnable(){public void run(){showPosts(a);}});}catch(final Exception e){runOnUiThread(new Runnable(){public void run(){feed.removeAllViews();feed.addView(tv("Search failed: "+e.getMessage(),16));}});}}}).start();}
  void composeDialog(){final EditText e=new EditText(this);e.setHint("What’s happening?");e.setMinLines(3);new AlertDialog.Builder(this).setTitle("Compose").setView(e).setNegativeButton("Cancel",null).setPositiveButton("Post",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){sendPost(e.getText().toString());}}).show();}
  void sendPost(final String text){if(text.trim().length()==0)return;new Thread(new Runnable(){public void run(){try{http("POST",base+"/1/statuses/update.json","status="+enc(text),token);runOnUiThread(new Runnable(){public void run(){toast("Posted");loadTimeline();}});}catch(final Exception e){runOnUiThread(new Runnable(){public void run(){toast("Post failed: "+e.getMessage());}});}}}).start();}
  void serverDialog(){final EditText e=new EditText(this);e.setText(base);new AlertDialog.Builder(this).setTitle("Server").setMessage("Bridge address (HTTP is intentional for Android 2.3)").setView(e).setNegativeButton("Cancel",null).setPositiveButton("Save",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){base=e.getText().toString().trim();if(base.endsWith("/"))base=base.substring(0,base.length()-1);getPreferences(0).edit().putString("server",base).commit();toast("Server saved");}}).show();}
  String http(String method,String url,String body,String auth)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod(method);c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setDoInput(true);if(auth!=null)c.setRequestProperty("Authorization","Bearer "+auth);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");OutputStream o=c.getOutputStream();o.write(body.getBytes("UTF-8"));o.close();}int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();if(in==null)throw new IOException("HTTP "+code);ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[2048];int n;while((n=in.read(b))!=-1)out.write(b,0,n);String s=new String(out.toByteArray(),"UTF-8");if(code>=400)throw new IOException("HTTP "+code+" "+s);return s;}
  String enc(String s)throws UnsupportedEncodingException{return URLEncoder.encode(s,"UTF-8");}String param(String s,String k){for(String x:s.split("&")){int i=x.indexOf('=');if(i>0&&x.substring(0,i).equals(k))try{return URLDecoder.decode(x.substring(i+1),"UTF-8");}catch(Exception e){}}return null;}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
